import sys

def can_transform(a, b):
    from collections import Counter

    # Count the frequency of each element in both multisets
    count_a = Counter(a)
    count_b = Counter(b)

    # Check if we can transform b to a
    for key in count_a:
        if key not in count_b or count_a[key] > count_b[key]:
            return False

        # Check if we can produce the required number of 'key' elements in b
        current_count = 0
        for num in sorted(b, reverse=True):
            if num % key == 0:
                while num % key == 0 and current_count < count_a[key]:
                    num //= 2
                    current_count += 1
                if current_count == count_a[key]:
                    break
        if current_count < count_a[key]:
            return False

    return True

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        a = list(map(int, data[index:index + n]))
        index += n
        b = list(map(int, data[index:index + n]))
        index += n

        if can_transform(a, b):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
